    routes = [routes[i] for i in range(len(routes)) if active[i]]

    # Insertion of any remaining nodes (kept from incumbent; typically empty).
    loads = [route_load(rt) for rt in routes]
    for node in remaining:
        if demands[node] > capacity:
            continue
        loads = [route_load(rt) for rt in routes]
        best_r = None
        best_pos = None
        best_delta = None
        for rid in range(len(routes)):
            if loads[rid] + demands[node] > capacity:
                continue
            rt = routes[rid]
            m = len(rt)
            for pos in range(m + 1):
                if m == 0:
                    delta = matrix[depot][node] + matrix[node][depot]
                else:
                    if pos == 0:
                        delta = matrix[depot][node] + matrix[node][rt[0]] - matrix[depot][rt[0]]
                    elif pos == m:
                        delta = matrix[rt[-1]][node] + matrix[node][depot] - matrix[rt[-1]][depot]
                    else:
                        a = rt[pos - 1]
                        b = rt[pos]
                        delta = matrix[a][node] + matrix[node][b] - matrix[a][b]
                if best_delta is None or delta < best_delta or (delta == best_delta and (rid, pos) < (best_r, best_pos)):
                    best_delta = delta
                    best_r = rid
                    best_pos = pos
        if best_r is None:
            routes.append([node])
            loads.append(demands[node])
        else:
            routes[best_r].insert(best_pos, node)
            loads[best_r] += demands[node]

    # Local search: improved intra-route 2-opt (small targeted evolution).
    def two_opt_on_route(rt):
        m = len(rt)
        if m < 4:
            return rt, False
        cur = route_cost(rt)

        take_best = (m <= 18)
        best_rt = rt
        best_delta = 0.0

        for i in range(m - 1):
            for k in range(i + 1, m):
                new_rt = rt[:i] + rt[i:k + 1][::-1] + rt[k + 1:]
                new_cost = route_cost(new_rt)
                delta = new_cost - cur
                if delta < -1e-9:
                    if not take_best:
                        return new_rt, True
                    if best_delta == 0.0 or delta < best_delta:
                        best_delta = delta
                        best_rt = new_rt
        if take_best and best_delta < -1e-9:
            return best_rt, True
        return rt, False

    for _ in range(2):
        changed = False
        for idx in range(len(routes)):
            new_rt, ok = two_opt_on_route(routes[idx])
            if ok:
                routes[idx] = new_rt
                changed = True
        if not changed:
            break

    loads = [route_load(rt) for rt in routes]

    def try_relocate(routes, loads):
        rcount = len(routes)
        for ra in range(rcount):
            if not routes[ra]:
                continue
            cost_a_before = route_cost(routes[ra])
            for pa in range(len(routes[ra])):
                node = routes[ra][pa]
                d = demands[node]
                if d > loads[ra]:
                    continue
                new_load_a = loads[ra] - d
                src_after = routes[ra][:pa] + routes[ra][pa + 1:]
                cost_a_after = route_cost(src_after)

                for rb in range(rcount):
                    if rb == ra:
                        continue
                    if loads[rb] + d > capacity:
                        continue
                    cost_b_before = route_cost(routes[rb])
                    rt_b = routes[rb]
                    m = len(rt_b)

                    best_pos = None
                    best_delta = None

                    if m == 0:
                        pos = 0
                        rt_new_b = [node]
                        delta = (cost_a_after + route_cost(rt_new_b)) - (cost_a_before + cost_b_before)
                        best_delta = delta
                        best_pos = pos
                    else:
                        for pos in range(m + 1):
                            rt_new_b = rt_b[:pos] + [node] + rt_b[pos:]
                            delta = (cost_a_after + route_cost(rt_new_b)) - (cost_a_before + cost_b_before)
                            if best_delta is None or delta < best_delta or (delta == best_delta and pos < best_pos):
                                best_delta = delta
                                best_pos = pos

                    if best_delta is not None and best_delta < -1e-9:
                        routes[ra] = src_after
                        routes[rb] = routes[rb][:best_pos] + [node] + routes[rb][best_pos:]
                        loads[ra] = new_load_a
                        loads[rb] += d
                        return True
        return False

    def try_swap(routes, loads):
        rcount = len(routes)
        costs = [route_cost(r) for r in routes]
        for ra in range(rcount):
            if not routes[ra]:
                continue
            for rb in range(ra + 1, rcount):
                if not routes[rb]:
                    continue
                ra_nodes = routes[ra]
                rb_nodes = routes[rb]
                for ia in range(len(ra_nodes)):
                    na = ra_nodes[ia]
                    da = demands[na]
                    for ib in range(len(rb_nodes)):
                        nb = rb_nodes[ib]
                        db = demands[nb]
                        new_load_ra = loads[ra] - da + db
                        new_load_rb = loads[rb] - db + da
                        if new_load_ra > capacity or new_load_rb > capacity:
                            continue
                        new_ra = ra_nodes[:ia] + [nb] + ra_nodes[ia + 1:]
                        new_rb = rb_nodes[:ib] + [na] + rb_nodes[ib + 1:]
                        new_cost_ra = route_cost(new_ra)
                        new_cost_rb = route_cost(new_rb)
                        delta = (new_cost_ra + new_cost_rb) - (costs[ra] + costs[rb])
                        if delta < -1e-9:
                            routes[ra] = new_ra
                            routes[rb] = new_rb
                            loads[ra] = new_load_ra
                            loads[rb] = new_load_rb
                            costs[ra] = new_cost_ra
                            costs[rb] = new_cost_rb
                            return True
        return False

    routes = [rt for rt in routes if rt]
    loads = [route_load(rt) for rt in routes]

    # Replay-aware: if looks like bottleneck structure, do a couple more inter-route relocation rounds.
    family = None
    if isinstance(desc, dict):
        family = desc.get("family", None)
    bottleneck = (family == "two_cluster_bottleneck")

    inter_rounds = 3 if bottleneck else 1
    for _ in range(inter_rounds):
        routes = [rt for rt in routes if rt]
        loads = [route_load(rt) for rt in routes]
        if len(routes) <= 1:
            break
        if try_relocate(routes, loads):
            continue
        if try_swap(routes, loads):
            continue
        break

    # One extra deterministic 2-opt sweep to clean up after inter-route changes.
    changed_any = True
    if bottleneck:
        limit = 2
    else:
        limit = 1
    for _ in range(limit):
        if not changed_any:
            break
        changed_any = False
        for idx in range(len(routes)):
            new_rt, ok = two_opt_on_route(routes[idx])
            if ok:
                routes[idx] = new_rt
                changed_any = True

    routes = [rt for rt in routes if rt]
